def submit_sku(sku, writer):
    return writer(sku)

def choose(title, products, writer):
    matches = [product for product in products if product["title"].casefold() == title.strip().casefold()]
    if not matches:
        return {"status": "not_found"}
    return submit_sku(matches[0]["title"], writer)

