artifacts.policies.py:
def legacy(attempt, record):
    if attempt == 4:
        record("terminal")
        return "done"
    return "retry"

def checked(attempt, record):
    if attempt == 4:
        return "done"
    return "retry"

artifacts.journal.py:
def accepted(state, document, persist):
    row = {"cursor": state["cursor"], "record_time": document["processed_at"], "state": "accepted"}
    persist(row)
    state["cursor"] += 1

def rejected(state, document, persist):
    row = {"cursor": state["cursor"], "record_time": document["published_on"], "state": "rejected"}
    state["cursor"] += 1
    persist(row)

artifacts.settings.py:
FIELD_NAMES = {"batch_size"}
ENV_NAMES = {"batch_size": "BATCH_SIZE"}

def runtime(values, environment):
    if set(values) - FIELD_NAMES:
        raise ValueError("unknown setting")
    size = int(values.get("batch_size", environment.get(ENV_NAMES["batch_size"], 40)))
    if size <= 0:
        raise ValueError("batch size must be positive")
    return {"batch_size": size}

